def countPalindromeDeletions(vals, succ):
    a = []
    cur = 0
    while cur != -1:
        a.append(vals[cur])
        cur = succ[cur]
    n = len(a)

    def run_len(p):
        lo = hi = p
        while lo > 0 and a[lo - 1] == a[p]:
            lo -= 1
        while hi < n - 1 and a[hi + 1] == a[p]:
            hi += 1
        return hi - lo + 1

    def ok_without(p):
        b = a[:p] + a[p + 1:]
        return b == b[::-1]

    i, j = 0, n - 1
    while i < j and a[i] == a[j]:
        i += 1
        j -= 1
    if i >= j:
        return run_len(n // 2)
    total = 0
    if ok_without(i):
        total += run_len(i)
    if ok_without(j):
        total += run_len(j)
    return total
